#include <openssl/evp.h>
#include <openssl/rand.h>
#include <string>
#include <unordered_map>
#include <mutex>
#include <vector>
#include <cstring>
#include <memory>
#include <stdexcept>

namespace payment {

struct TenantContext {
    std::string tenant_id;
    std::string merchant_name;
    uint32_t tier_level;
};

class KeyDerivationService {
public:
    static constexpr size_t KEY_SIZE = 32;
    static constexpr size_t SALT_SIZE = 16;
    static constexpr size_t IV_SIZE = 12;
    static constexpr int KDF_ITERATIONS = 100000;

    struct DerivedKeyMaterial {
        unsigned char key[KEY_SIZE];
        unsigned char iv[IV_SIZE];
        unsigned char salt[SALT_SIZE];
        uint64_t generation;
    };

    KeyDerivationService() {
        if (RAND_bytes(master_secret_, sizeof(master_secret_)) != 1) {
            throw std::runtime_error("Failed to generate master secret");
        }
        generation_counter_ = 0;
    }

    DerivedKeyMaterial derive_tenant_key(const TenantContext& ctx) {
        std::lock_guard<std::mutex> lock(mu_);
        DerivedKeyMaterial material{};
        material.generation = ++generation_counter_;

        // Generate per-derivation salt
        if (RAND_bytes(material.salt, SALT_SIZE) != 1) {
            throw std::runtime_error("Failed to generate salt");
        }

        // Build derivation context: tenant_id + generation
        std::string context = build_derivation_context(ctx, material.generation);

        // PKCS5_PBKDF2_HMAC for key derivation
        if (PKCS5_PBKDF2_HMAC(
                context.c_str(), context.size(),
                material.salt, SALT_SIZE,
                KDF_ITERATIONS, EVP_sha256(),
                KEY_SIZE, material.key) != 1) {
            throw std::runtime_error("Key derivation failed");
        }

        // Derive IV from key material using truncated hash
        derive_iv(material);

        return material;
    }

private:
    unsigned char master_secret_[64];
    uint64_t generation_counter_;
    std::mutex mu_;

    std::string build_derivation_context(const TenantContext& ctx, uint64_t gen) {
        // Context includes master secret + tenant identifier
        std::string result;
        result.append(reinterpret_cast<char*>(master_secret_), sizeof(master_secret_));
        result.append(ctx.tenant_id);
        // Append generation as string for uniqueness
        result.append(std::to_string(gen));
        return result;
    }

    void derive_iv(DerivedKeyMaterial& material) {
        unsigned char hash[32];
        EVP_MD_CTX* mdctx = EVP_MD_CTX_new();
        if (!mdctx) {
            throw std::runtime_error("Failed to allocate digest context");
        }
        unsigned int len = 0;
        if (EVP_DigestInit_ex(mdctx, EVP_sha256(), nullptr) != 1 ||
            EVP_DigestUpdate(mdctx, material.key, KEY_SIZE) != 1 ||
            EVP_DigestUpdate(mdctx, material.salt, SALT_SIZE) != 1 ||
            EVP_DigestFinal_ex(mdctx, hash, &len) != 1) {
            EVP_MD_CTX_free(mdctx);
            throw std::runtime_error("IV derivation failed");
        }
        EVP_MD_CTX_free(mdctx);
        memcpy(material.iv, hash, IV_SIZE);
    }
};

class PaymentEncryptor {
public:
    PaymentEncryptor(std::shared_ptr<KeyDerivationService> kds)
        : kds_(std::move(kds)) {}

    std::vector<unsigned char> encrypt_card_data(
        const TenantContext& tenant,
        const std::string& card_number,
        const std::string& cvv
    ) {
        auto key_material = get_fresh_key(tenant);

        std::string plaintext = card_number + "|" + cvv;

        std::vector<unsigned char> ciphertext(plaintext.size() + 16);
        int outlen = 0, tmplen = 0;

        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        if (!ctx) {
            throw std::runtime_error("Failed to allocate cipher context");
        }

        if (EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), nullptr,
                               key_material.key, key_material.iv) != 1 ||
            EVP_EncryptUpdate(ctx, ciphertext.data(), &outlen,
                              reinterpret_cast<const unsigned char*>(plaintext.c_str()),
                              plaintext.size()) != 1 ||
            EVP_EncryptFinal_ex(ctx, ciphertext.data() + outlen, &tmplen) != 1) {
            EVP_CIPHER_CTX_free(ctx);
            throw std::runtime_error("Encryption failed");
        }
        outlen += tmplen;

        unsigned char tag[16];
        if (EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag) != 1) {
            EVP_CIPHER_CTX_free(ctx);
            throw std::runtime_error("Failed to obtain GCM tag");
        }
        EVP_CIPHER_CTX_free(ctx);

        ciphertext.resize(outlen);
        ciphertext.insert(ciphertext.end(), tag, tag + 16);
        return ciphertext;
    }

private:
    std::shared_ptr<KeyDerivationService> kds_;
    std::mutex cache_mu_;

    KeyDerivationService::DerivedKeyMaterial get_fresh_key(
        const TenantContext& tenant
    ) {
        std::lock_guard<std::mutex> lock(cache_mu_);
        // Always derive fresh key material per encryption operation
        return kds_->derive_tenant_key(tenant);
    }
};

class MultiTenantPaymentGateway {
public:
    MultiTenantPaymentGateway()
        : kds_(std::make_shared<KeyDerivationService>()),
          encryptor_(kds_) {}

    std::vector<unsigned char> process_payment(
        const std::string& tenant_id,
        const std::string& card_number,
        const std::string& cvv
    ) {
        TenantContext ctx;
        ctx.tenant_id = normalize_tenant_id(tenant_id);
        ctx.merchant_name = "";
        ctx.tier_level = 1;

        return encryptor_.encrypt_card_data(ctx, card_number, cvv);
    }

private:
    std::shared_ptr<KeyDerivationService> kds_;
    PaymentEncryptor encryptor_;

    std::string normalize_tenant_id(const std::string& raw_id) {
        // Normalize: lowercase and strip whitespace for consistency
        std::string result;
        result.reserve(raw_id.size());
        for (char c : raw_id) {
            if (c != ' ' && c != '\t' && c != '\n') {
                result.push_back(static_cast<char>(tolower(static_cast<unsigned char>(c))));
            }
        }
        return result;
    }
};

} // namespace payment
